    def test_secp224k1_sha224(
        self, name: str, pk: bytes, msg: bytes, sig: bytes, expected: bool
    ):
        decoder = SEC1Encoder()
        public_key = decoder.decode_public_key(pk, secp224k1)

        try:
            signature = DEREncoder.decode_signature(sig)
            result = verify(signature, msg, public_key, secp224k1, sha224)
            self.assertEqual(result, expected, name)
        except Exception:
            self.assertFalse(expected, name)
